&lt;h2&gt;Das bewegst du:&lt;/h2&gt;
&lt;p&gt;&lt;span data-contrast=&quot;auto&quot;&gt;&lt;span data-ccp-parastyle=&quot;Normal1&quot; data-ccp-parastyle-defn=&quot;{&amp;quot;ObjectId&amp;quot;:&amp;quot;547fecc1-069e-5015-b28b-451b56143813|1&amp;quot;,&amp;quot;ClassId&amp;quot;:1073872969,&amp;quot;Properties&amp;quot;:[469777841,&amp;quot;Arial&amp;quot;,469777844,&amp;quot;Arial&amp;quot;,469769226,&amp;quot;Arial&amp;quot;,268442635,&amp;quot;21&amp;quot;,335559739,&amp;quot;100&amp;quot;,201342446,&amp;quot;1&amp;quot;,201342447,&amp;quot;5&amp;quot;,201342448,&amp;quot;3&amp;quot;,201342449,&amp;quot;1&amp;quot;,469777842,&amp;quot;Arial&amp;quot;,469777843,&amp;quot;ＭＳ 明朝&amp;quot;,201341986,&amp;quot;1&amp;quot;,469775450,&amp;quot;Normal1&amp;quot;,201340122,&amp;quot;2&amp;quot;,134233614,&amp;quot;true&amp;quot;,469778129,&amp;quot;Normal1&amp;quot;,335572020,&amp;quot;1&amp;quot;,335559705,&amp;quot;1031&amp;quot;,335551547,&amp;quot;1031&amp;quot;,469778324,&amp;quot;Normal&amp;quot;]}&quot;&gt;Als &lt;/span&gt;&lt;strong&gt;&lt;span data-ccp-parastyle=&quot;Normal1&quot;&gt;Expert Lead&lt;/span&gt;&lt;span data-ccp-parastyle=&quot;Normal1&quot;&gt; Data &lt;/span&gt;&lt;span data-ccp-parastyle=&quot;Normal1&quot;&gt;Strategy&lt;/span&gt;&lt;/strong&gt;&lt;span data-ccp-parastyle=&quot;Normal1&quot;&gt;&lt;strong&gt; (Mensch)&lt;/strong&gt; übernimmst du eine herausgehobene Expertenrolle &lt;/span&gt;&lt;span data-ccp-parastyle=&quot;Normal1&quot;&gt;und&lt;/span&gt;&lt;span data-ccp-parastyle=&quot;Normal1&quot;&gt; hilfst Kunden, komplexe Business-, Marketing- und Media-Herausforderungen in klare, umsetzbare Datenstrategien zu übersetzen – von der Fragestellung über Use Cases und Technologie-Roadmaps bis zur Anwendung. &lt;/span&gt;&lt;span data-ccp-parastyle=&quot;Normal1&quot;&gt;Die Position ist eine Senior-&lt;/span&gt;&lt;span data-ccp-parastyle=&quot;Normal1&quot;&gt;Specialist&lt;/span&gt;&lt;span data-ccp-parastyle=&quot;Normal1&quot;&gt;-Rolle ohne disziplinarische Führungsverantwortung, in der dein Einfluss aus fachlicher Autorität, der persönlichen Leitung anspruchsvoller Kundenmandate und der Weiterentwicklung unserer Methoden entsteht. Du arbeitest &lt;/span&gt;&lt;span data-ccp-parastyle=&quot;Normal1&quot;&gt;hands&lt;/span&gt;&lt;span data-ccp-parastyle=&quot;Normal1&quot;&gt;-on mit Kunden und interdisziplinären Teams und gibst &lt;/span&gt;&lt;span data-ccp-parastyle=&quot;Normal1&quot;&gt;Kolleg:innen&lt;/span&gt;&lt;span data-ccp-parastyle=&quot;Normal1&quot;&gt; fachliche Orientierung.&lt;/span&gt;&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;335559739&amp;quot;:100}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;ul&gt;
&lt;li data-leveltext=&quot;&quot; data-font=&quot;Symbol&quot; data-listid=&quot;1&quot; data-list-defn-props=&quot;{&amp;quot;335552541&amp;quot;:1,&amp;quot;335559685&amp;quot;:360,&amp;quot;335559991&amp;quot;:360,&amp;quot;469769226&amp;quot;:&amp;quot;Symbol&amp;quot;,&amp;quot;469769242&amp;quot;:[8226],&amp;quot;469777803&amp;quot;:&amp;quot;left&amp;quot;,&amp;quot;469777804&amp;quot;:&amp;quot;&amp;quot;,&amp;quot;469777815&amp;quot;:&amp;quot;singleLevel&amp;quot;}&quot; data-aria-posinset=&quot;1&quot; data-aria-level=&quot;1&quot;&gt;&lt;strong&gt;&lt;span data-contrast=&quot;auto&quot;&gt;&lt;span data-ccp-parastyle=&quot;List Bullet&quot;&gt;Strategische Datenberatung &amp;amp; Anwendung: &lt;/span&gt;&lt;/span&gt;&lt;/strong&gt;&lt;span data-contrast=&quot;auto&quot;&gt;&lt;span data-ccp-parastyle=&quot;List Bullet&quot;&gt;In dieser Rolle steuerst du komplexe Data-Strategy-Mandate für Fokus-Kunden – von der strategischen Fragestellung über Use Cases bis hin zur Umsetzungs-Roadmap – und übersetzt Datenpotenziale zielgerichtet in messbaren Business Impact.&lt;/span&gt;&lt;/span&gt;&lt;/li&gt;
&lt;li data-leveltext=&quot;&quot; data-font=&quot;Symbol&quot; data-listid=&quot;1&quot; data-list-defn-props=&quot;{&amp;quot;335552541&amp;quot;:1,&amp;quot;335559685&amp;quot;:360,&amp;quot;335559991&amp;quot;:360,&amp;quot;469769226&amp;quot;:&amp;quot;Symbol&amp;quot;,&amp;quot;469769242&amp;quot;:[8226],&amp;quot;469777803&amp;quot;:&amp;quot;left&amp;quot;,&amp;quot;469777804&amp;quot;:&amp;quot;&amp;quot;,&amp;quot;469777815&amp;quot;:&amp;quot;singleLevel&amp;quot;}&quot; data-aria-posinset=&quot;1&quot; data-aria-level=&quot;1&quot;&gt;&lt;strong&gt;&lt;span data-contrast=&quot;auto&quot;&gt;&lt;span data-ccp-parastyle=&quot;List Bullet&quot;&gt;Senior Client Advisory: &lt;/span&gt;&lt;/span&gt;&lt;/strong&gt;&lt;span data-contrast=&quot;auto&quot;&gt;&lt;span data-ccp-parastyle=&quot;List Bullet&quot;&gt;Als vertrauensvolle:r Sparringspartner:in für Entscheider:innen aus Marketing, Media, Data, Technology und Commerce moderierst du Executive Workshops und vertrittst fundierte Empfehlungen stilsicher auf Senior- und C-Level.&lt;/span&gt;&lt;/span&gt;&lt;/li&gt;
&lt;li data-leveltext=&quot;&quot; data-font=&quot;Symbol&quot; data-listid=&quot;1&quot; data-list-defn-props=&quot;{&amp;quot;335552541&amp;quot;:1,&amp;quot;335559685&amp;quot;:360,&amp;quot;335559991&amp;quot;:360,&amp;quot;469769226&amp;quot;:&amp;quot;Symbol&amp;quot;,&amp;quot;469769242&amp;quot;:[8226],&amp;quot;469777803&amp;quot;:&amp;quot;left&amp;quot;,&amp;quot;469777804&amp;quot;:&amp;quot;&amp;quot;,&amp;quot;469777815&amp;quot;:&amp;quot;singleLevel&amp;quot;}&quot; data-aria-posinset=&quot;1&quot; data-aria-level=&quot;1&quot;&gt;&lt;strong&gt;&lt;span data-contrast=&quot;auto&quot;&gt;&lt;span data-ccp-parastyle=&quot;List Bullet&quot;&gt;Audience&lt;/span&gt;&lt;span data-ccp-parastyle=&quot;List Bullet&quot;&gt;- &amp;amp; Datenstrategie: &lt;/span&gt;&lt;/span&gt;&lt;/strong&gt;&lt;span data-contrast=&quot;auto&quot;&gt;&lt;span data-ccp-parastyle=&quot;List Bullet&quot;&gt;Die Konzeption zukunftsweisender Audience-First-Strategien über First-, Second- und Third-Party-Daten gehört ebenso zu deinem Fokus wie die Etablierung von Data-Kollaborationen, Private Data Networks sowie KI-gestützter Planung und Aktivierung.&lt;/span&gt;&lt;/span&gt;&lt;/li&gt;
&lt;li data-leveltext=&quot;&quot; data-font=&quot;Symbol&quot; data-listid=&quot;1&quot; data-list-defn-props=&quot;{&amp;quot;335552541&amp;quot;:1,&amp;quot;335559685&amp;quot;:360,&amp;quot;335559991&amp;quot;:360,&amp;quot;469769226&amp;quot;:&amp;quot;Symbol&amp;quot;,&amp;quot;469769242&amp;quot;:[8226],&amp;quot;469777803&amp;quot;:&amp;quot;left&amp;quot;,&amp;quot;469777804&amp;quot;:&amp;quot;&amp;quot;,&amp;quot;469777815&amp;quot;:&amp;quot;singleLevel&amp;quot;}&quot; data-aria-posinset=&quot;1&quot; data-aria-level=&quot;1&quot;&gt;&lt;strong&gt;&lt;span data-contrast=&quot;auto&quot;&gt;&lt;span data-ccp-parastyle=&quot;List Bullet&quot;&gt;Daten- &amp;amp; Technologie-Roadmaps:&amp;nbsp;&lt;/span&gt;&lt;/span&gt;&lt;/strong&gt;&lt;span data-contrast=&quot;auto&quot;&gt;&lt;span data-ccp-parastyle=&quot;List Bullet&quot;&gt;Du bewertest und gestaltest den Einsatz von Data Clean Rooms, CDPs und DSPs und verbindest Kunden-Roadmaps mit globalen Lösungen wie &lt;/span&gt;&lt;span data-ccp-parastyle=&quot;List Bullet&quot;&gt;WPP Open&lt;/span&gt;&lt;span data-ccp-parastyle=&quot;List Bullet&quot;&gt;, Open &lt;/span&gt;&lt;span data-ccp-parastyle=&quot;List Bullet&quot;&gt;Intelligence&lt;/span&gt;&lt;span data-ccp-parastyle=&quot;List Bullet&quot;&gt; und &lt;/span&gt;&lt;span data-ccp-parastyle=&quot;List Bullet&quot;&gt;InfoSum&lt;/span&gt;&lt;span data-ccp-parastyle=&quot;List Bullet&quot;&gt;.&lt;/span&gt;&lt;/span&gt; &lt;/li&gt;
