&lt;li data-leveltext=&quot;&quot; data-font=&quot;Symbol&quot; data-listid=&quot;1&quot; data-list-defn-props=&quot;{&amp;quot;335552541&amp;quot;:1,&amp;quot;335559685&amp;quot;:360,&amp;quot;335559991&amp;quot;:360,&amp;quot;469769226&amp;quot;:&amp;quot;Symbol&amp;quot;,&amp;quot;469769242&amp;quot;:[8226],&amp;quot;469777803&amp;quot;:&amp;quot;left&amp;quot;,&amp;quot;469777804&amp;quot;:&amp;quot;&amp;quot;,&amp;quot;469777815&amp;quot;:&amp;quot;singleLevel&amp;quot;}&quot; data-aria-posinset=&quot;1&quot; data-aria-level=&quot;1&quot;&gt;&lt;strong&gt;&lt;span data-contrast=&quot;auto&quot;&gt;&lt;span data-ccp-parastyle=&quot;List Bullet&quot;&gt;Fachliche Führung &amp;amp;&amp;nbsp;&lt;/span&gt;&lt;span data-ccp-parastyle=&quot;List Bullet&quot;&gt;Capability&lt;/span&gt;&lt;span data-ccp-parastyle=&quot;List Bullet&quot;&gt; Building: &lt;/span&gt;&lt;/span&gt;&lt;/strong&gt;&lt;span data-contrast=&quot;auto&quot;&gt;&lt;span data-ccp-parastyle=&quot;List Bullet&quot;&gt;Als Subject Matter Expert setzt du maßgebliche Standards für Audience-Strategien, Governance und datenbasierte Entscheidungsprozesse. Neben Executive Briefings, POVs und der fundierten Einordnung von Markt-, Tech-, Datenschutz- und KI-Trends stärkst du Kolleg:innen gezielt durch Coaching und kontinuierlichen Wissenstransfer.&lt;/span&gt;&lt;/span&gt;&lt;/li&gt;
&lt;li data-leveltext=&quot;&quot; data-font=&quot;Symbol&quot; data-listid=&quot;1&quot; data-list-defn-props=&quot;{&amp;quot;335552541&amp;quot;:1,&amp;quot;335559685&amp;quot;:360,&amp;quot;335559991&amp;quot;:360,&amp;quot;469769226&amp;quot;:&amp;quot;Symbol&amp;quot;,&amp;quot;469769242&amp;quot;:[8226],&amp;quot;469777803&amp;quot;:&amp;quot;left&amp;quot;,&amp;quot;469777804&amp;quot;:&amp;quot;&amp;quot;,&amp;quot;469777815&amp;quot;:&amp;quot;singleLevel&amp;quot;}&quot; data-aria-posinset=&quot;1&quot; data-aria-level=&quot;1&quot;&gt;&lt;strong&gt;&lt;span data-contrast=&quot;auto&quot;&gt;&lt;span data-ccp-parastyle=&quot;List Bullet&quot;&gt;Business Development &amp;amp;&amp;nbsp;&lt;/span&gt;&lt;span data-ccp-parastyle=&quot;List Bullet&quot;&gt;Thought&lt;/span&gt;&lt;span data-ccp-parastyle=&quot;List Bullet&quot;&gt; Leadership:&amp;nbsp;&lt;/span&gt;&lt;/span&gt;&lt;/strong&gt;&lt;span data-contrast=&quot;auto&quot;&gt;&lt;span data-ccp-parastyle=&quot;List Bullet&quot;&gt;Deine Expertise bringst du wirkungsvoll in Pitches, belastbare Business Cases und Cross-/Upselling-Potenziale ein. Durch hochkarätige Case Studies und POVs positionierst du WPP Media nachhaltig als Vordenker für moderne Datenstrategien und datengetriebene Lösungen.&lt;/span&gt;&lt;/span&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;&amp;nbsp;&lt;/p&gt;
